const MONTHS = ['JANUARI','FEBRUARI','MARET','APRIL','MEI','JUNI','JULI','AGUSTUS','SEPTEMBER','OKTOBER','NOVEMBER','DESEMBER'];
const bodyItem = $input.first().json;
const src = bodyItem.data && typeof bodyItem.data === 'object' ? bodyItem.data : bodyItem;
const msg = src || {};
const text = String(msg.body || '');
const now = msg.timestamp ? new Date(Number(msg.timestamp) * 1000) : new Date();
const sheetName = now.getDate() + ' ' + MONTHS[now.getMonth()] + ' ' + now.getFullYear();

const FIELD_TO_COLUMN = { RUANGAN:'C','KAPA SITAS TTO':'D','KAPA SITAS RIIL':'E','SISA AWAL':'F',ISI:'G',KOSONG:'H','BOR (%)':'I',BARU:'J',PINDAHAN:'K',PULANG:'L','KASUS MEDIKAL':'M','KASUS BEDAH':'N','KASUS OBGYN':'O','CARA BAYAR JKN':'P','CARA BAYAR TUNAI':'Q','CARA BAYAR ASRNS':'R','LAMA RAWAT II':'S','LOS RS':'T',TOI:'U','RENCANA PULANG':'V',RUJUK:'W',PINDAH:'X','RENCANA PINDAH':'Y',MNGL:'Z','OPERASI ELEKTIF':'AB',CITO:'AC',POLI:'AD',HD:'AE',CRRT:'AF',BC:'AG','CATH LAB':'AH',PENUNJANG:'AI',ECHO:'AJ',USG:'AK',ENDOSCOPY:'AL',LAIN:'AM',PESAN:'AN',KETERANGAN:'AO'};

const ALIASES = { ruangan:'RUANGAN', ruang:'RUANGAN', kamar:'RUANGAN', 'kapasitas tto':'KAPA SITAS TTO', tto:'KAPA SITAS TTO', kapasitas:'KAPA SITAS TTO', 'kapasitas riil':'KAPA SITAS RIIL', riil:'KAPA SITAS RIIL', 'sisa awal':'SISA AWAL', sisa:'SISA AWAL', isi:'ISI', kosong:'KOSONG', bor:'BOR (%)', 'bor (%)':'BOR (%)', 'bor%':'BOR (%)', baru:'BARU', pindahan:'PINDAHAN', pulang:'PULANG', 'kasus medikal':'KASUS MEDIKAL', medikal:'KASUS MEDIKAL', 'kasus bedah':'KASUS BEDAH', bedah:'KASUS BEDAH', 'kasus obgyn':'KASUS OBGYN', obgyn:'KASUS OBGYN', 'cara bayar jkn':'CARA BAYAR JKN', jkn:'CARA BAYAR JKN', 'cara bayar tunai':'CARA BAYAR TUNAI', tunai:'CARA BAYAR TUNAI', 'cara bayar asrns':'CARA BAYAR ASRNS', asrns:'CARA BAYAR ASRNS', 'lama rawat ii':'LAMA RAWAT II', 'lama rawat':'LAMA RAWAT II', 'los rs':'LOS RS', los:'LOS RS', toi:'TOI', 'rencana pulang':'RENCANA PULANG', rujuk:'RUJUK', pindah:'PINDAH', 'rencana pindah':'RENCANA PINDAH', mnngl:'MNGL', mnl:'MNGL', 'operasi elektif':'OPERASI ELEKTIF', operasi:'OPERASI ELEKTIF', elektif:'OPERASI ELEKTIF', cito:'CITO', poli:'POLI', hd:'HD', crrt:'CRRT', bc:'BC', 'cath lab':'CATH LAB', cath:'CATH LAB', penunjang:'PENUNJANG', echo:'ECHO', usg:'USG', endoscopy:'ENDOSCOPY', endoskopi:'ENDOSCOPY', lain:'LAIN', lainnya:'LAIN', pesan:'PESAN', catatan:'PESAN', keterangan:'KETERANGAN', ket:'KETERANGAN' };

const lines = text.split(/\r?\n/);
const sheetMap = {};
const metadata = {
  waktu: now.toISOString(),
  grup: (msg.chatId || '').replace('@g.us', ''),
  pengirim: msg.contact?.pushName || msg.contact?.name || msg.author || '',
  nomor: (msg.author || msg.from || '').split('@')[0],
  raw: msg.body || '',
};
for (const line of lines) {
  const m = line.match(/^\s*([^:|\t]+?)\s*[:|\t]\s*(.*)$/);
  if (m) {
    const rawKey = m[1].trim().toLowerCase();
    const val = m[2].trim();
    if (!val) continue;
    const canonical = ALIASES[rawKey] || rawKey;
    const col = FIELD_TO_COLUMN[canonical];
    if (col) sheetMap[col] = val;
  }
}
return [{ json: { sheetName, sheetMap, ruangan: sheetMap['C'] || '', ...metadata } }];
